answerCalls.rawCandidateText:
{
  "directAnswer": "Under Singapore tax law, expenses and capital allowances relating to passenger motor cars are subject to specific statutory restrictions. Specifically, accounting depreciation on a passenger car is not tax-deductible, and capital allowances on certain private passenger motor cars are restricted under the Income Tax Act 1947, subject to vehicle- and business-specific exceptions.",
  "keyRules": [
    "Accounting depreciation is disallowed for tax purposes, and Capital Allowances (CA) are granted instead on qualifying plant and machinery used in trade or business under Sections 19 and 19A of the Income Tax Act 1947.",
    "Section 15(1)(k) of the Income Tax Act 1947 generally disallows expenses incurred in respect of passenger motor cars and capital allowances on private and business cars, subject to vehicle- and business-specific exceptions."
  ],
  "caveats": [
    "The vehicle category, registration date, and specific business use (e.g., whether it is registered as a private hire car or used for specific commercial transport operations) must be verified before determining whether a deduction or capital allowance is available.",
    "Missing facts: Business purpose, vehicle registration type (e.g. Q-plated vs. RU-plated vs. private hire car), and supporting invoices/receipts."
  ],
  "statuteReferences": [
    {
      "standard": "Income Tax Act 1947",
      "paragraph": "Section 14(1)",
      "authority": "IRAS",
      "officialSourceUrl": "https://sso.agc.gov.sg/Act/ITA1947?ProvIds=pr14-"
    },
