answerCalls.rawCandidateText:
{
  "directAnswer": "IR21 is the tax clearance form that an employer in Singapore is required to file with the Inland Revenue Authority of Singapore (IRAS) when a non-citizen employee (such as a foreigner holding an Employment Pass, S Pass, Work Permit, or Dependant's Pass) ceases employment in Singapore, leaves Singapore for an overseas posting, or leaves Singapore for a substantial period exceeding 3 months.",
  "keyRules": [
    "Filing Deadline: The employer must file Form IR21 at least 1 month before the employee's cessation of employment, departure from Singapore, or overseas posting date.",
    "Tax Withholding Obligation: The employer must withhold all monies due to the employee (including salary, bonus, overtime pay, severance, and gratuities) starting from the date the employer is aware of the employee's cessation or departure, for a period of up to 30 days or until tax clearance is received from IRAS, whichever is earlier."
  ],
  "caveats": [
    "Filing Exemption: Filing Form IR21 may not be required under specific administrative concessions, such as when a foreigner remains employed by the same Singapore entity while travelling overseas for short business trips, or under specific earnings thresholds and conditions outlined by IRAS.",
    "Missing Fact: Employee citizenship or permanent-resident status, precise employment cessation/departure details, and whether an IR21 exemption applies to the specific employee."
  ],
  "statuteReferences": [
    {
      "standard": "Income Tax Act 1947",
      "paragraph": "Section 83",
      "authority": "IRAS",
      "officialSourceUrl": "https://sso.agc.gov.sg/Act/ITA1947"
    }
  ]
}

